inbound.set-body:
@{
            // Read the incoming REST JSON body
            var body = context.Request.Body.As(preserveContent: true);

            // Build the GraphQL query string
            var graphqlQuery = @"
                query Offer($searchInput: OfferRequest!) {
                    getOffers(input: $searchInput) {
                        airBounds {
                            airBoundId
                            airlineCode
                            connections {
                                origin { airportCode }
                                destination { airportCode }
                                departureDateTime
                                arrivalDateTime
                                flightNumber
                                cabinType
                            }
                            price {
                                total { value currencyCode }
                                base  { value currencyCode }
                                taxes { value currencyCode }
                            }
                            fareFamily
                        }
                    }
                }";

            // Compose the full GraphQL request payload
            var graphqlPayload = new JObject(
                new JProperty("query", graphqlQuery),
                new JProperty("variables", new JObject(
                    new JProperty("searchInput", body)
                ))
            );

            return graphqlPayload.ToString();
        }

outbound.set-body:
@{
            var response = context.Response.Body.As(preserveContent: true);
            var getOffers = response["data"]?["getOffers"];
            return getOffers != null ? getOffers.ToString() : response.ToString();
        }
